static int popcount(uint32_t x) { int n = 0; while (x) { x &= x - 1; n++; } return n; }   // clears the lowest set bit each time

int main(void) {
    uint32_t v[] = {0, 1, 12, 255, 1024, 0xF0F0F0F0u};
    for (int i = 0; i < 6; i++) {
        uint32_t x = v[i];
        printf("%10u  bits=%2d  power of two=%d  lowest set bit=%u\n", x, popcount(x), x && !(x & (x - 1)), x & -x);
    }
    return 0;
}

