#include <stdio.h>
#include <stdlib.h>

static int cmp(const void *a, const void *b) {
    int x = *(const int *)a, y = *(const int *)b;
    return (x > y) - (x < y);          // never x - y: that overflows for large values
}

int main(void) {
    int v[] = {42, -7, 19, 0, 3, 3, 1000000, -1000000};
    int n = sizeof v / sizeof v[0];
    qsort(v, n, sizeof v[0], cmp);
    for (int i = 0; i < n; i++) printf("%d ", v[i]);
    printf("\n");
    return 0;
}

