#include <stdio.h>
#include <stdint.h>

static uint64_t calls;
static uint64_t fib_slow(int n) { calls++; return n < 2 ? n : fib_slow(n - 1) + fib_slow(n - 2); }
static uint64_t memo[91];
static uint64_t fib_fast(int n) { calls++; if (n < 2) return n; if (memo[n]) return memo[n]; return memo[n] = fib_fast(n - 1) + fib_fast(n - 2); }

int main(void) {
    calls = 0; uint64_t a = fib_slow(30); printf("fib_slow(30) = %llu with %llu calls\n", (unsigned long long)a, (unsigned long long)calls);
    calls = 0; uint64_t b = fib_fast(90); printf("fib_fast(90) = %llu with %llu calls\n", (unsigned long long)b, (unsigned long long)calls);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node { int value; struct node *next; };

static struct node *push(struct node *head, int v) {
    struct node *n = malloc(sizeof *n);
    n->value = v; n->next = head; return n;
}
static struct node *reverse(struct node *head) {
    struct node *prev = NULL;
    while (head) { struct node *next = head->next; head->next = prev; prev = head; head = next; }
    return prev;
}

int main(void) {
    struct node *list = NULL;
    for (int i = 1; i <= 5; i++) list = push(list, i * i);
    for (struct node *p = list; p; p = p->next) printf("%d ", p->value);
    printf("\n");
    list = reverse(list);
    while (list) { struct node *n = list; printf("%d ", n->value); list = n->next; free(n); }
    printf("\n");
    return 0;
}

#include <stdio.h>

static int lower_bound(const int *a, int n, int key) {      // first index with a[i] >= key
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;                        // not (lo + hi) / 2: that can overflow
        if (a[mid] < key) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int main(void) {
    int a[] = {1, 3, 3, 3, 8, 13, 21, 34};
    int keys[] = {0, 3, 4, 34, 100};
    for (int i = 0; i < 5; i++) printf("lower_bound(%3d) = %d\n", keys[i], lower_bound(a, 8, keys[i]));
    return 0;
}

#include <stdio.h>
#include <string.h>

#define N 100

int main(void) {
    char composite[N + 1]; memset(composite, 0, sizeof composite);
    for (int i = 2; i * i <= N; i++)
        if (!composite[i]) for (int j = i * i; j <= N; j += i) composite[j] = 1;
    int count = 0;
    for (int i = 2; i <= N; i++) if (!composite[i]) { printf("%d ", i); count++; }
    printf("\n%d primes up to %d\n", count, N);
    return 0;
}

